function dayCard(d){let k=iso(d),a=(S.data.sessions||[]).filter(s=>s.session_date===k),n=(S.data.nutritionDays||[]).find(x=>x.nutrition_date===k);return `<article class="day-card ${k===iso(new Date())?'today':''}"><div class="day-head"><strong>${days[d.getDay()]}</strong><span>${d.getDate()}</span></div>${a.map(s=>`<div class="plan-item ${s.training_type}"><b>${esc(s.title)}</b><span>${title(s.training_type)}${s.duration_minutes?' · '+s.duration_minutes+' min':''}</span></div>`).join('')}<div class="plan-item steps"><b>Steps</b><span>${Number(S.client.daily_steps_goal||0).toLocaleString()} target</span></div>${n?`<div class="plan-item nutrition"><b>Nutrition</b><span>${n.calorie_target||'—'} kcal</span></div>`:''}<button class="text-btn">+ Add</button></article>`}
