function macros(){let c=S.client,p=S.data.nutritionPlans?.[0]||{};return `<div class="macro-row"><div class="macro"><span>Calories</span><strong>${c.calorie_goal||p.calories||'—'}</strong></div><div class="macro"><span>Protein</span><strong>${c.protein_goal_g||p.protein_g||'—'}g</strong></div><div class="macro"><span>Carbs</span><strong>${c.carbs_goal_g||p.carbs_g||'—'}g</strong></div><div class="macro"><span>Fat</span><strong>${c.fat_goal_g||p.fat_g||'—'}g</strong></div></div>`}
function nutrition(){$('#body').innerHTML=`<div class="panel-head"><div><h3>Nutrition</h3><span class="sub">Targets first. Meals underneath.</span></div><button class="btn primary small">+ Day type</button></div>${macros()}<div style="height:16px"></div>${(S.data.nutritionPlans||[]).map(p=>`<section class="panel"><div class="panel-head"><h3>${esc(p.name)}</h3><span class="pill">${p.days_per_week}× / WEEK</span></div>${(p.meals||[]).map(m=>`<div class="meal-card"><h3>${esc(m.name)}</h3>${(m.items||[]).map(i=>`<p><b>${esc(i.name)}</b><span class="sub">${esc(i.description||'')}</span></p>`).join('')}</div>`).join('')}</section>`).join('')}`}
function checkins(){$('#body').innerHTML=(S.data.checkins||[]).length?S.data.checkins.map(c=>`<article class="checkin-card"><div class="panel-head"><div><b>Week ${c.week_number||'—'}</b><span class="sub">${fmt(c.submitted_at)}</span></div><div class="score">${c.week_score||'—'}/10</div></div><div class="detail-list"><div class="detail"><label>Weight</label>${c.weight_kg||'—'} kg</div><div class="detail"><label>Training</label>${c.training_adherence??'—'}%</div><div class="detail"><label>Nutrition</label>${c.nutrition_adherence??'—'}%</div><div class="detail"><label>Steps</label>${c.average_steps||'—'}</div></div><p><b>Win</b><br>${esc(c.wins||'—')}</p><p><b>Challenge</b><br>${esc(c.challenges||'—')}</p><label class="field">Coach response<textarea data-table="checkins" data-id="${c.id}" data-field="coach_response">${esc(c.coach_response||'')}</textarea></label></article>`).join(''):'<div class="empty">No check-ins yet.</div>';autosave()}
function progress(){let a=S.data.progress||[];$('#body').innerHTML=`<section class="panel"><div class="panel-head"><h3>Historical progress</h3><span class="pill">${a.length} ENTRIES</span></div>${a.length?a.map(r=>`<div class="note-row"><b>${fmt(r.entry_date)}</b><span style="float:right">${r.weight_kg||'—'} kg · waist ${r.waist_cm||'—'} cm</span></div>`).join(''):'<div class="empty">No entries yet.</div>'}</section>`}
function onboarding(){let r=S.data.onboarding?.[0]?.responses||{},fields=Array.isArray(r.fields)?r.fields.filter(x=>x.value!==null&&x.value!==''&&!['hidden','file'].includes(x.type)):[],raw=r.text||'';$('#body').innerHTML=(fields.length||raw)?`<section class="panel" style="margin-bottom:12px"><div class="panel-head"><h3>Onboarding answers</h3><span class="pill">IMPORTED</span></div>${fields.length?`<div class="onboard-grid">${fields.map(f=>`<div class="detail"><label>${esc(f.label||f.name||f.id||'Response')}</label>${esc(f.type==='checkbox'?(f.checked?'Yes':'No'):f.value)}</div>`).join('')}</div>`:''}${raw?`<details style="margin-top:16px"><summary>Complete original response</summary><pre class="source-record">${esc(raw)}</pre></details>`:''}</section>${legalRecords()}`:'<div class="empty">No onboarding response imported yet.</div>'}
function legalRecords(){let records=S.data.legal||[],raw=(S.data.assessments||[]).filter(x=>x.assessment_type==='legal');return `<section class="panel"><div class="panel-head"><h3>Legal, consent & documents</h3><span class="pill">${records.length+raw.length} RECORDS</span></div>${records.map(x=>`<div class="note-row"><b>${esc(x.consent_type||x.document_name||'Consent record')}</b><span class="sub">${fmt(x.accepted_at||x.created_at)}</span><p>${esc(x.status||'Recorded')}</p></div>`).join('')}${raw.map(x=>`<details class="note-row"><summary>${esc(x.coach_summary||'Imported legal record')}</summary><pre class="source-record">${esc(x.responses?.text||JSON.stringify(x.responses,null,2))}</pre></details>`).join('')||(!records.length?'<div class="empty">No legal records found.</div>':'')}</section>`}
function diagnostics(){let reports=S.data.diagnostics||[];$('#body').innerHTML='<div class="panel-head"><div><h3>Diagnostic reports</h3><span class="sub">Bloodwork and Nutrition Genome history.</span></div><button class="btn primary small" id="newDiagnostic">+ Import JSON</button></div><div id="diagnosticForm"></div>'+(reports.length?reports.map(reportCard).join(''):'<div class="empty">No diagnostic reports for this client.</div>');$('#newDiagnostic').onclick=diagnosticImportForm}
function reportCard(r){let d=r.data||{},markers=Array.isArray(d.markers)?d.markers:[],gen=d.genetic_data||{},flagged=markers.filter(m=>!['optimal','normal'].includes(String(m.status||m.classification||'').toLowerCase()));return '<article class="checkin-card"><div class="panel-head"><div><span class="eyebrow">'+esc((r.report_type||'report').toUpperCase())+'</span><h3>'+esc(r.title)+'</h3><span class="sub">'+fmt(r.report_date)+' · '+esc(d.lab_source||'Lab not recorded')+' · '+esc(d.status||'imported')+'</span></div>'+(d.health_score?'<div class="score">'+esc(d.health_score)+'</div>':'')+'</div>'+(r.summary?'<p>'+esc(r.summary)+'</p>':'')+(markers.length?'<div class="metric-strip"><div class="metric"><span>MARKERS</span><strong>'+markers.length+'</strong></div><div class="metric"><span>FLAGGED</span><strong>'+flagged.length+'</strong></div></div><details><summary>All biomarkers and reference ranges</summary><div class="diagnostic-markers">'+markers.map(m=>'<div class="note-row"><b>'+esc(m.marker_name||m.name)+'</b><span style="float:right">'+esc(m.value)+' '+esc(m.unit||'')+'</span><span class="sub">'+esc(m.status||m.classification||'')+' · '+esc(m.reference_range_low??'—')+'–'+esc(m.reference_range_high??'—')+'</span></div>').join('')+'</div></details>':'')+(Object.keys(gen).length?'<details><summary>Genetics coaching insights</summary><pre class="source-record">'+esc(JSON.stringify(gen,null,2))+'</pre></details>':'')+'<details><summary>Recommendations and complete source JSON</summary><pre class="source-record">'+esc(JSON.stringify(d,null,2))+'</pre></details>'+(d.loom_url?'<p><a href="'+esc(d.loom_url)+'" target="_blank" rel="noopener">Open Loom walkthrough</a></p>':'')+'</article>'}
function diagnosticImportForm(){$('#diagnosticForm').innerHTML='<form id="diagnosticImport" class="panel checkin-form" style="margin-bottom:18px"><label class="field">Report type<select name="report_type"><option value="bloodwork">Bloodwork</option><option value="genetics">Genetics</option></select></label><label class="field">Report date<input name="report_date" type="date" required></label><label class="field">Lab source<input name="lab_source" placeholder="Quest, Randox, Nutrition Genome…"></label><label class="field wide">Report title<input name="title" value="Diagnostic Report" required></label><label class="field wide">Paste exported JSON<textarea name="json" rows="12" required></textarea></label><div class="wide"><button class="btn primary">Import report</button></div></form>';$('#diagnosticImport').onsubmit=saveDiagnostic}
async function saveDiagnostic(e){e.preventDefault();let f=new FormData(e.target),data;try{data=JSON.parse(f.get('json'))}catch{return toast('That is not valid JSON')}data={...data,lab_source:f.get('lab_source')||data.lab_source};let payload={client_id:S.client.id,report_type:f.get('report_type'),report_date:f.get('report_date'),title:f.get('title'),summary:data.coach_summary||data.genetic_data?.overview||null,data};let{error}=await db.from('diagnostic_reports').insert(payload);if(error)return toast(error.message);await loadData(S.client.id);toast('Diagnostic report imported');diagnostics()}
function notes(){$('#body').innerHTML=`<section class="panel"><label class="field">Add coach note<textarea id="note"></textarea></label><button class="btn primary small" id="saveNote">Save note</button>${(S.data.notes||[]).map(n=>`<div class="note-row"><span class="pill">${esc(n.category||'general')}</span><span class="sub">${fmt(n.occurred_at)}</span><p>${esc(n.note)}</p></div>`).join('')}</section>`;$('#saveNote').onclick=async()=>{let note=$('#note').value.trim();if(!note)return;if(S.preview){S.data.notes.unshift({note,occurred_at:new Date().toISOString()});toast('Note saved');return notes()}let{error}=await db.from('coach_notes').insert({client_id:S.client.id,coach_id:S.user.id,note});if(error)return toast(error.message);await loadData(S.client.id);notes()}}
function autosave(){$$('[data-table]').forEach(e=>{let t;e.oninput=()=>{clearTimeout(t);t=setTimeout(()=>save(e),650)};e.onblur=()=>{clearTimeout(t);save(e)}})}async function save(e){if(!e.dataset.id)return;if(S.preview)return toast('Saved');let{error}=await db.from(e.dataset.table).update({[e.dataset.field]:e.value}).eq('id',e.dataset.id);toast(error?error.message:'Saved')}
function currentWeek(){let t=iso(new Date());return S.data.weeks?.find(w=>{let e=new Date(w.week_start+'T12:00:00');e.setDate(e.getDate()+7);return t>=w.week_start&&t<iso(e)})||S.data.weeks?.[0]}
function renderClient(){({today:clientToday,training:clientTraining,nutrition:clientNutrition,checkin:clientCheckin,progress:clientProgress}[S.clientView])()}const clientHead=(k,t,s)=>`<span class="eyebrow">${k}</span><h1>${t}</h1><p class="muted">${s}</p>`;
function clientToday(){let c=S.client,w=currentWeek(),today=iso(new Date()),a=S.data.sessions.filter(s=>s.session_date===today),tasks=[...a.map(s=>({id:s.id,type:'session',name:s.title,sub:title(s.training_type),done:s.status==='completed'})),{type:'steps',name:`${Number(c.daily_steps_goal||0).toLocaleString()} steps`,sub:'Daily target',done:false},...S.data.habits.map(h=>({id:h.id,type:'habit',name:h.name,sub:'Daily habit',done:false}))];$('#clientMain').innerHTML=clientHead(days[new Date().getDay()].toUpperCase(),`Today, ${S.profile.full_name.split(' ')[0]}.`,w?.coach_note||'Everything you need today.')+`<div class="today-grid"><section><div class="panel-head"><h3>Today’s plan</h3><span class="pill">${tasks.filter(x=>x.done).length}/${tasks.length} COMPLETE</span></div><div class="today-list">${tasks.map(task).join('')}</div></section><aside class="panel"><div class="panel-head"><h3>Nutrition targets</h3></div>${macros()}<div style="height:18px"></div><b>Weekly check-in</b><span class="sub">${days[c.checkin_day??5]}</span></aside></div>`;wireTasks()}
function task(x){return `<label class="task ${x.done?'done':''}"><input type="checkbox" data-type="${x.type}" data-id="${x.id||''}" ${x.done?'checked':''}><div><b>${esc(x.name)}</b><span class="sub">${esc(x.sub)}</span></div><span>›</span></label>`}function wireTasks(){$$('[data-type]').forEach(e=>e.onchange=async()=>{if(S.preview)return e.closest('.task').classList.toggle('done',e.checked);if(e.dataset.type==='session')await db.from('training_sessions').update({status:e.checked?'completed':'planned',completed_at:e.checked?new Date().toISOString():null}).eq('id',e.dataset.id);if(e.dataset.type==='habit')await db.from('habit_logs').upsert({habit_id:e.dataset.id,log_date:iso(new Date()),completed:e.checked},{onConflict:'habit_id,log_date'});await loadData(S.client.id);renderClient()})}
function clientTraining(){let w=currentWeek(),a=S.data.sessions.filter(s=>s.week_id===w?.id),types={weights:'Weights',resistance:'Resistance',cardio:'Cardio',steps:'Steps'};$('#clientMain').innerHTML=clientHead('YOUR PROGRAMME','Training','Four clear areas. Open only what you need.')+`<div class="type-grid">${Object.entries(types).map(([k,v])=>{let r=a.filter(s=>s.training_type===k),done=r.filter(s=>s.status==='completed').length;return `<div class="type-card"><span class="eyebrow">${v.toUpperCase()}</span><strong>${k==='steps'?Number(S.client.daily_steps_goal||0).toLocaleString()+' / day':done+'/'+r.length+' complete'}</strong><div class="progress-bar"><i style="width:${r.length?done/r.length*100:0}%"></i></div></div>`}).join('')}</div>${Object.entries(types).filter(([k])=>k!=='steps').map(([k,v])=>`<section class="panel" style="margin-bottom:12px"><div class="panel-head"><h3>${v}</h3></div>${a.filter(s=>s.training_type===k).length?a.filter(s=>s.training_type===k).map(s=>`<div class="programme-day">${task({id:s.id,type:'session',name:s.title,sub:fmt(s.session_date,{weekday:'long',day:'numeric',month:'short'}),done:s.status==='completed'})}${S.data.exercises.filter(e=>e.session_id===s.id).map(e=>`<div class="exercise-row"><b>${esc(e.name)}</b><span>${e.sets||'—'}</span><span>${esc(e.reps||'—')}</span><span>${esc(e.load||'—')}</span><span>${e.rest_seconds?e.rest_seconds+'s':'—'}</span></div>`).join('')}</div>`).join(''):'<div class="empty">Nothing scheduled.</div>'}</section>`).join('')}`;wireTasks()}
function clientNutrition(){$('#clientMain').innerHTML=clientHead('FUEL THE WEEK','Nutrition','Targets first. Food options underneath.')+macros()+`<div style="height:18px"></div>${S.data.nutritionPlans.map(p=>`<section class="panel"><div class="panel-head"><h3>${esc(p.name)}</h3><span class="pill">${p.days_per_week}× / WEEK</span></div>${(p.meals||[]).map(m=>`<div class="meal-card"><h3>${esc(m.name)}</h3>${(m.items||[]).map(i=>`<p><b>${esc(i.name)}</b><br><span class="muted">${esc(i.description||'')}</span></p>`).join('')}</div>`).join('')}</section>`).join('')}`}
function clientCheckin(){$('#clientMain').innerHTML=clientHead('WEEKLY REVIEW','Check-in','Give your coach the full picture, not just the scale.')+`<form id="ci" class="panel checkin-form">${[['weight_kg','Weight (kg)'],['week_score','Week score'],['average_steps','Average steps'],['energy','Energy 1–10'],['sleep','Sleep 1–10'],['stress','Stress 1–10'],['hunger','Hunger 1–10'],['cravings','Cravings 1–10'],['training_adherence','Training adherence %'],['nutrition_adherence','Nutrition adherence %']].map(x=>`<label class="field">${x[1]}<input name="${x[0]}" type="number" step="0.1"></label>`).join('')}${[['wins','Biggest win'],['challenges','Biggest challenge'],['make_next_week_better','What will make next week better?'],['support_needed','What support do you need?'],['client_notes','Anything else?']].map(x=>`<label class="field wide">${x[1]}<textarea name="${x[0]}"></textarea></label>`).join('')}<div class="wide"><button class="btn primary">Submit check-in</button></div></form>`;$('#ci').onsubmit=submitCI}async function submitCI(e){e.preventDefault();if(S.preview)return toast('Check-in submitted — preview');let p={client_id:S.client.id,week_number:currentWeek()?.week_number};for(let[k,v]of new FormData(e.target))p[k]=v===''?null:(e.target.elements[k].type==='number'?Number(v):v);let{error}=await db.from('checkins').insert(p);if(error)return toast(error.message);toast('Check-in submitted')}
function clientProgress(){$('#clientMain').innerHTML=clientHead('THE LONG VIEW','Progress','The trend matters more than any single day.')+`<div class="grid-2"><section class="panel">${S.data.progress.map(r=>`<div class="note-row"><b>${fmt(r.entry_date)}</b><span style="float:right">${r.weight_kg||'—'} kg</span></div>`).join('')||'<div class="empty">No entries.</div>'}</section><form id="pr" class="panel"><label class="field">Weight (kg)<input name="weight_kg" type="number" step="0.1"></label><label class="field">Waist (cm)<input name="waist_cm" type="number" step="0.1"></label><label class="field">Steps<input name="steps" type="number"></label><button class="btn primary">Save progress</button></form></div>`;$('#pr').onsubmit=submitProgress}async function submitProgress(e){e.preventDefault();if(S.preview)return toast('Progress saved — preview');let p={client_id:S.client.id,entry_date:iso(new Date())};for(let[k,v]of new FormData(e.target))p[k]=v?Number(v):null;let{error}=await db.from('progress_entries').upsert(p,{onConflict:'client_id,entry_date'});if(error)return toast(error.message);toast('Progress saved')}
const baseOverview=overview,baseTraining=training,baseNotes=notes;
overview=function(){baseOverview();let c=S.client;$('#body').insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:16px"><div class="panel-head"><div><h3>Client setup & goals</h3><span class="sub">Weight tracking is optional. Archiving never deletes history.</span></div></div><form id="clientSettings" class="checkin-form"><label class="field">Status<select name="status"><option value="active">Active</option><option value="inactive">Inactive</option><option value="archived">Archived</option></select></label><label class="field">Market<select name="market_region"><option value="">Not set</option><option value="ireland">Ireland</option><option value="us">United States</option><option value="uk">United Kingdom</option><option value="other">Other</option></select></label><label class="field">Primary goal<select name="goal_type"><option value="">Not set</option><option value="lose_weight">Lose weight</option><option value="gain_weight">Gain weight</option><option value="maintain_weight">Maintain weight</option><option value="performance">Performance</option><option value="health">Health</option><option value="body_composition">Body composition</option><option value="other">Other</option></select></label><label class="field">Goal weight (optional)<input name="goal_weight_kg" type="number" step="0.1" value="${c.goal_weight_kg??''}"></label><label class="field wide">Goal details<textarea name="goal_summary">${esc(c.goal_summary||'')}</textarea></label><label class="field"><input name="track_weight" type="checkbox" ${c.track_weight!==false?'checked':''}> Track body weight</label><div class="wide"><button class="btn primary">Save client setup</button></div></form></section>`);let f=$('#clientSettings');f.status.value=c.status||'active';f.market_region.value=c.market_region||'';f.goal_type.value=c.goal_type||'';f.onsubmit=saveClientSettings}
async function saveClientSettings(e){e.preventDefault();let f=e.target,p={status:f.status.value,market_region:f.market_region.value||null,goal_type:f.goal_type.value||null,goal_weight_kg:f.goal_weight_kg.value?Number(f.goal_weight_kg.value):null,goal_summary:f.goal_summary.value||null,track_weight:f.track_weight.checked,archived_at:f.status.value==='archived'?(S.client.archived_at||new Date().toISOString()):null};let{data,error}=await db.from('clients').update(p).eq('id',S.client.id).select().single();if(error)return toast(error.message);Object.assign(S.client,data);toast('Client setup saved');overview()}
training=async function(){let{data:logs}=await db.from('exercise_logs').select('*').eq('client_id',S.client.id).order('performed_at',{ascending:false}).limit(500),all=(S.data.programs||[]),types=['weights','resistance','cardio','steps'];$('#body').innerHTML=`<div class="panel-head"><div><h3>Training programme & history</h3><span class="sub">Weights, resistance, cardio and steps remain separate.</span></div></div><div class="type-grid">${types.map(t=>`<div class="type-card"><span class="eyebrow">${t.toUpperCase()}</span><strong>${all.flatMap(p=>p.days||[]).filter(d=>d.training_type===t).length} days</strong></div>`).join('')}</div>`+types.map(t=>`<section class="panel" style="margin:14px 0"><div class="panel-head"><h3>${title(t)}</h3></div>${programHTML(all.map(p=>({...p,days:(p.days||[]).filter(d=>d.training_type===t)})).filter(p=>p.days.length))||'<div class="empty">Nothing assigned.</div>'}</section>`).join('')+`<section class="panel"><div class="panel-head"><div><h3>Logged performance history</h3><span class="sub">Loads stay here when programmes change.</span></div><span class="pill">${(logs||[]).length} SETS</span></div>${(logs||[]).map(x=>`<div class="note-row"><b>${esc(x.exercise_name)}</b><span style="float:right">${x.load??'—'} ${esc(x.load_unit||'kg')} × ${x.reps??'—'}</span><span class="sub">${fmt(x.performed_at)}</span></div>`).join('')||'<div class="empty">No historical set logs recovered yet.</div>'}</section>`}
notes=async function(){baseNotes();let raw=(S.data.assessments||[]).filter(x=>x.assessment_type==='messages'),{data:msgs}=await db.from('messages').select('*').eq('client_id',S.client.id).order('sent_at',{ascending:false}).limit(1000);$('#body').insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:16px"><div class="panel-head"><h3>Messages & communication history</h3><span class="pill">${(msgs||[]).length+raw.length} RECORDS</span></div>${(msgs||[]).map(m=>`<div class="note-row"><b>${esc(m.sender_role||'Message')}</b><span class="sub">${fmt(m.sent_at)}</span><p>${esc(m.body||m.message||'')}</p></div>`).join('')}${raw.map(x=>`<details class="note-row"><summary>Imported coach-visible message record</summary><pre class="source-record">${esc(x.responses?.text||JSON.stringify(x.responses,null,2))}</pre></details>`).join('')||(!(msgs||[]).length?'<div class="empty">No messages found.</div>':'')}</section>`)}
const baseRoster=roster;
roster=function(){let count=v=>S.clients.filter(c=>v==='archived'?(c.status==='archived'||c.archived_at):c.status===v).length;$('#coachMain').innerHTML=head('CLIENT MANAGEMENT','Clients',`<input class="search" placeholder="Search clients…"><select id="clientFilter"><option value="all">All ${S.clients.length}</option><option value="active">Active ${count('active')}</option><option value="inactive">Inactive ${count('inactive')}</option><option value="archived">Archived ${count('archived')}</option></select><button class="btn primary">+ Add client</button>`)+`<section class="panel">${rows(S.clients)}</section>`;wireRows();$('#clientFilter').onchange=e=>{let v=e.target.value;$$('.client-row').forEach(r=>{let c=S.clients.find(x=>x.id===r.dataset.id),ok=v==='all'||(v==='archived'?(c.status==='archived'||c.archived_at):c.status===v);r.classList.toggle('hidden',!ok)})}}

const displayWeight=kg=>{if(kg==null||kg==='')return '—';return S.client.weight_unit==='lbs'?`${(Number(kg)*2.20462).toFixed(1)} lb`:`${Number(kg).toFixed(1)} kg`};
function lineChart(values,color='#c7a55b'){let a=values.filter(x=>Number.isFinite(Number(x))).map(Number);if(a.length<2)return '<div class="empty chart-empty">Not enough data for a trend yet.</div>';let min=Math.min(...a),max=Math.max(...a),range=max-min||1,pts=a.map((v,i)=>`${10+i*280/(a.length-1)},${100-(v-min)*80/range}`).join(' ');return `<svg class="trend-chart" viewBox="0 0 300 120" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity=".35"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><polyline points="10,110 ${pts} 290,110" fill="url(#area)" stroke="none"/><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="3" vector-effect="non-scaling-stroke"/></svg>`}
progress=function(){let a=[...(S.data.progress||[])].sort((x,y)=>String(x.entry_date).localeCompare(String(y.entry_date))),cis=[...(S.data.checkins||[])].sort((x,y)=>String(x.submitted_at).localeCompare(String(y.submitted_at))),weights=a.filter(x=>x.weight_kg!=null),latest=weights.at(-1),first=weights[0];$('#body').innerHTML=`<div class="performance-hero"><div><span class="eyebrow">PERFORMANCE TREND</span><h2>${displayWeight(latest?.weight_kg)}</h2><span class="sub">${first&&latest?((Number(latest.weight_kg)-Number(first.weight_kg))*(S.client.weight_unit==='lbs'?2.20462:1)).toFixed(1)+' '+(S.client.weight_unit==='lbs'?'lb':'kg')+' since first record':'Historical weight'}</span></div><div class="hero-score"><strong>${weights.length}</strong><span>WEIGH-INS</span></div></div><div class="chart-grid"><section class="panel chart-panel"><div class="panel-head"><div><h3>Body weight</h3><span class="sub">All recovered entries · ${esc(S.client.weight_unit||'kg')}</span></div></div>${lineChart(weights.map(x=>x.weight_kg))}</section><section class="panel chart-panel"><div class="panel-head"><div><h3>Energy, sleep & stress</h3><span class="sub">Weekly check-in trend</span></div></div>${lineChart(cis.map(x=>x.energy),'#4cc9a4')}</section><section class="panel chart-panel"><div class="panel-head"><div><h3>Training adherence</h3><span class="sub">Check-in percentages</span></div></div>${lineChart(cis.map(x=>x.training_adherence),'#5da9e9')}</section><section class="panel chart-panel"><div class="panel-head"><div><h3>Nutrition adherence</h3><span class="sub">Check-in percentages</span></div></div>${lineChart(cis.map(x=>x.nutrition_adherence),'#d98585')}</section></div><section class="panel"><div class="panel-head"><h3>Complete measurement history</h3><span class="pill">${a.length} RECORDS</span></div><div class="data-table"><div class="data-head"><span>Date</span><span>Weight</span><span>Waist</span><span>Steps</span></div>${[...a].reverse().map(r=>`<div class="data-row"><b>${fmt(r.entry_date)}</b><span>${displayWeight(r.weight_kg)}</span><span>${r.waist_cm??'—'} cm</span><span>${r.steps?Number(r.steps).toLocaleString():'—'}</span></div>`).join('')}</div></section>`}
checkins=function(){let a=S.data.checkins||[];$('#body').innerHTML=`<div class="performance-hero"><div><span class="eyebrow">CHECK-IN HISTORY</span><h2>${a.length} weekly reviews</h2><span class="sub">Nothing is removed when a programme changes.</span></div><div class="hero-score"><strong>${a[0]?.week_score??'—'}</strong><span>LATEST SCORE</span></div></div>`+(a.map(c=>`<details class="checkin-card rich-checkin" ${c===a[0]?'open':''}><summary><div><span class="eyebrow">WEEK ${c.week_number||'—'}</span><h3>${fmt(c.submitted_at)}</h3></div><div class="score">${c.week_score||'—'}/10</div></summary><div class="detail-list"><div class="detail"><label>Weight</label>${displayWeight(c.weight_kg)}</div><div class="detail"><label>Energy</label>${c.energy??'—'}/10</div><div class="detail"><label>Sleep</label>${c.sleep??'—'}/10</div><div class="detail"><label>Stress</label>${c.stress??'—'}/10</div><div class="detail"><label>Training</label>${c.training_adherence??'—'}%</div><div class="detail"><label>Nutrition</label>${c.nutrition_adherence??'—'}%</div><div class="detail"><label>Average steps</label>${c.average_steps?Number(c.average_steps).toLocaleString():'—'}</div></div><div class="report-copy"><h4>Wins</h4><p>${esc(c.wins||'—')}</p><h4>Challenges</h4><p>${esc(c.challenges||'—')}</p><h4>Training summary</h4><p>${esc(c.training_summary||'—')}</p><h4>Nutrition summary</h4><p>${esc(c.food_summary||'—')}</p><h4>Client notes</h4><p>${esc(c.client_notes||'—')}</p><label class="field">Coach response<textarea data-table="checkins" data-id="${c.id}" data-field="coach_response">${esc(c.coach_response||'')}</textarea></label></div></details>`).join('')||'<div class="empty">No check-ins were present in the old app.</div>');autosave()}
const priorTraining=training;
training=async function(){await priorTraining();let h=$('#body .panel-head');h?.insertAdjacentHTML('beforeend','<button class="btn gold small" id="trainingPrompt">AI import prompt</button>');$('#trainingPrompt').onclick=()=>showImportPrompt('training')}
const priorNutrition=nutrition;
nutrition=function(){priorNutrition();let h=$('#body .panel-head');h?.insertAdjacentHTML('beforeend','<button class="btn gold small" id="nutritionPrompt">AI import prompt</button>');$('#nutritionPrompt').onclick=()=>showImportPrompt('nutrition');let raw=(S.data.assessments||[]).find(x=>x.assessment_type==='nutrition');if(raw?.responses?.text)$('#body').insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:16px"><div class="panel-head"><div><h3>Complete original nutrition record</h3><span class="sub">Coach-visible information recovered from the old app.</span></div><span class="pill">IMPORTED</span></div><pre class="source-record">${esc(raw.responses.text)}</pre></section>`)}
function showImportPrompt(kind){let trainingPrompt=`Create a Legal Edge training programme as valid JSON only. Structure: {"name":"Programme name","description":"","days":[{"title":"Day 1 - Upper","training_type":"weights","day_index":0,"coach_notes":"","recovery_notes":"","exercises":[{"name":"Incline Dumbbell Press","sets":3,"reps":"8-12","load":"","rest_seconds":90,"tempo":"","tracking_type":"weight_reps","notes":"","coach_instructions":"","video_url":""}]}]}. training_type must be weights, resistance, cardio, steps, mobility or recovery. For cardio include instructions in coach_notes. Never invent client history or previous loads.`;let nutritionPrompt=`Create a Legal Edge nutrition plan as valid JSON only. Structure: {"name":"Nutrition Plan","day_types":[{"name":"Training Day","days_per_week":4,"calories":2200,"protein_g":180,"carbs_g":220,"fat_g":65,"coach_notes":"","meals":[{"name":"Breakfast","items":[{"name":"Meal option","description":"Exact foods, portions and substitutions"}]}],"busy_day_alternatives":["Option 1"]}]}. Include a full seven-day allocation, food preferences, restrictions and practical alternatives. Do not invent allergies or medical details.`;let prompt=kind==='training'?trainingPrompt:nutritionPrompt;$('#body').insertAdjacentHTML('afterbegin',`<section class="panel import-prompt"><div class="panel-head"><div><span class="eyebrow">AI IMPORT</span><h3>${title(kind)} JSON prompt</h3></div><button class="btn primary small" id="copyPrompt">Copy prompt</button></div><pre class="source-record">${esc(prompt)}</pre></section>`);$('#copyPrompt').onclick=async()=>{await navigator.clipboard.writeText(prompt);toast('Prompt copied')}}
const priorPlanner=planner;
planner=function(){let w=S.data.weeks?.[0];if(w)return priorPlanner();$('#body').innerHTML=`<div class="performance-hero"><div><span class="eyebrow">MONDAY — SUNDAY</span><h2>Build this week from the programme</h2><span class="sub">Training, cardio, mobility, recovery, steps and nutrition will remain editable.</span></div><button class="btn primary" id="generateWeek">Generate weekly plan</button></div><div class="week-grid">${[1,2,3,4,5,6,0].map((d,i)=>`<article class="day-card"><div class="day-head"><strong>${days[d]}</strong><span>${i+1}</span></div><div class="plan-item steps"><b>Steps</b><span>${Number(S.client.daily_steps_goal||0).toLocaleString()} target</span></div><div class="plan-item nutrition"><b>Nutrition</b><span>${S.client.calorie_goal||'—'} kcal</span></div></article>`).join('')}</div>`;$('#generateWeek').onclick=generateWeekFromProgramme}
async function generateWeekFromProgramme(){let program=(S.data.programs||[]).find(p=>p.status==='active')||S.data.programs?.[0];if(!program)return toast('Assign a training programme first');let st=monday(new Date()),{data:w,error}=await db.from('program_weeks').insert({client_id:S.client.id,week_start:iso(st),week_number:weeks(S.client.start_date),title:`Week ${weeks(S.client.start_date)}`,goal_weight_kg:S.client.track_weight?S.client.goal_weight_kg:null}).select().single();if(error)return toast(error.message);for(let d of program.days||[]){let date=new Date(+st+(Math.max(0,Math.min(6,d.day_index||0)))*864e5);await db.from('training_sessions').insert({week_id:w.id,programme_day_id:d.id,session_date:iso(date),training_type:d.training_type,title:d.title,notes:d.coach_notes,status:'planned'})}await loadData(S.client.id);toast('Weekly plan generated');planner()}
function mealBlocks(p){let text=p?.coach_notes||'',part=text.split(/MEAL PLAN/i)[1]?.split(/SUPPLEMENTS/i)[0]||'';return part.split(/\n\s*Add Item\s*/i).map((block,i)=>{let l=block.split('\n').map(x=>x.trim()).filter(x=>x&&!/^\d+\s*\/\s*7|^DAYS\/WEEK|^Delete day type|^Add Meal|^Total:|^Training Day|^Rest Day|^Non-Training Day/i.test(x));if(!l.length)return null;return {title:l[0],lines:l.slice(1)}}).filter(Boolean).filter(x=>x.lines.length)}
function mealPlanCard(p){let blocks=mealBlocks(p);return `<section class="meal-plan-card"><div class="panel-head"><div><h3>${esc(p.name)}</h3><span class="sub">${p.day_type||'Plan'} · ${p.days_per_week||'—'} days/week</span></div><span class="pill">${p.calories||'—'} kcal</span></div><div class="macro-row compact"><div class="macro"><span>Protein</span><strong>${p.protein_g||'—'}g</strong></div><div class="macro"><span>Carbs</span><strong>${p.carbs_g||'—'}g</strong></div><div class="macro"><span>Fat</span><strong>${p.fat_g||'—'}g</strong></div></div><div class="meal-grid">${blocks.map(b=>`<article class="meal-detail"><span class="eyebrow">${esc(b.title)}</span><div class="meal-lines">${b.lines.map((x,i)=>`<p class="${/kcal|protein|carbs|fat/i.test(x)?'meal-macros':''}">${esc(x)}</p>`).join('')}</div></article>`).join('')||`<pre class="source-record">${esc(p.coach_notes||'No meal details recorded.')}</pre>`}</div></section>`}
nutrition=function(){let plans=S.data.nutritionPlans||[];$('#body').innerHTML=`<div class="panel-head"><div><h3>Nutrition plans</h3><span class="sub">Exact recovered foods, weighed ingredients and client-specific targets.</span></div><button class="btn gold small" id="nutritionPrompt">AI import prompt</button></div>${plans.map(mealPlanCard).join('')||'<div class="empty">No structured nutrition plan recovered.</div>'}<section class="panel import-prompt"><div class="panel-head"><h3>Nutrition history source</h3><span class="pill">READ ONLY IMPORT</span></div><p class="sub">The original meal-plan text is retained below where the legacy app did not expose individual rows.</p>${plans.map(p=>`<details><summary>${esc(p.name)} · complete source record</summary><pre class="source-record">${esc(p.coach_notes||'')}</pre></details>`).join('')}</section>`;$('#nutritionPrompt').onclick=()=>showImportPrompt('nutrition')}
clientNutrition=function(){let plans=S.data.nutritionPlans||[];$('#clientMain').innerHTML=clientHead('FUEL THE WEEK','Nutrition','Your targets and weighed meal options, in your local units.')+`<div class="macro-row">${[['Calories','calorie_goal',''],['Protein','protein_goal_g','g'],['Carbs','carbs_goal_g','g'],['Fat','fat_goal_g','g']].map(x=>`<div class="macro"><span>${x[0]}</span><strong>${S.client[x[1]]||'—'}${x[2]}</strong></div>`).join('')}</div>${plans.map(mealPlanCard).join('')||'<div class="empty">Your coach has not published a meal plan yet.</div>'}`}
function milestoneCards(){let p=[...(S.data.progress||[])].filter(x=>x.weight_kg!=null).sort((a,b)=>String(a.entry_date).localeCompare(String(b.entry_date))),first=p[0]?.weight_kg,last=p.at(-1)?.weight_kg,down=first&&last?Math.max(0,(Number(first)-Number(last))*(S.client.weight_unit==='lbs'?2.20462:1)):0,streak=Math.min(4,S.data.checkins?.length||0);let cards=[];if(down>=5)cards.push(['🏆','5-pound milestone','You are down at least 5 lb from your first recorded weight.']);if(streak>=4)cards.push(['🔥','Four-week consistency','Four weekly check-ins recorded. Keep the run going.']);if((S.data.checkins||[]).some(x=>(x.training_adherence||0)>=90))cards.push(['⚡','Training consistency','A week at 90%+ training adherence.']);return cards.map(x=>`<div class="milestone"><span>${x[0]}</span><div><b>${x[1]}</b><small>${x[2]}</small></div></div>`).join('')}
const oldClientToday=clientToday;
clientToday=function(){oldClientToday();let m=milestoneCards();if(m)$('#clientMain').insertAdjacentHTML('afterbegin',`<section class="milestones"><div class="panel-head"><div><span class="eyebrow">WINS</span><h3>Progress milestones</h3></div><span class="sub">Keep ticking off the week</span></div>${m}</section>`)}
const oldClientCheckin=clientCheckin;
clientCheckin=function(){oldClientCheckin();let w=currentWeek(),s=(S.data.sessions||[]).filter(x=>x.week_id===w?.id);if(s.length)$('#clientMain').insertAdjacentHTML('afterbegin',`<section class="panel weekly-tick"><div class="panel-head"><div><span class="eyebrow">CHECK-IN DAY</span><h3>Tick off this week</h3><span class="sub">Your coach can see these completions.</span></div><span class="pill" id="tickCount">0/${s.length}</span></div>${s.map(x=>`<label class="task ${x.status==='completed'?'done':''}"><input type="checkbox" data-session-tick="${x.id}" ${x.status==='completed'?'checked':''}><div><b>${esc(x.title)}</b><span class="sub">${title(x.training_type)} · ${fmt(x.session_date,{weekday:'long',day:'numeric',month:'short'})}</span></div></label>`).join('')}</section>`);let ticks=$$('input[data-session-tick]');let update=()=>$('#tickCount')&&( $('#tickCount').textContent=ticks.filter(x=>x.checked).length+'/'+ticks.length+' COMPLETE');ticks.forEach(e=>e.onchange=async()=>{if(!S.preview)await db.from('training_sessions').update({status:e.checked?'completed':'planned',completed_at:e.checked?new Date().toISOString():null}).eq('id',e.dataset.sessionTick);e.closest('.task').classList.toggle('done',e.checked);update()});update()}
const recText=v=>Array.isArray(v)?v.join('\n'):typeof v==='object'?JSON.stringify(v,null,2):(v||'No guidance recorded.');
const recommendation=(label,value,accent)=>`<section class="report-section" style="--accent:${accent}"><span class="eyebrow">${label}</span><pre>${esc(recText(value))}</pre></section>`;
reportCard=function(r){let d=r.data||{},markers=Array.isArray(d.markers)?d.markers:[],gen=d.genetic_data||{},flagged=markers.filter(m=>!['optimal','normal'].includes(String(m.status||m.classification||'').toLowerCase()));return `<article class="diagnostic-report"><header class="report-cover"><div><span class="eyebrow">${esc((r.report_type||'report').toUpperCase())} · ${fmt(r.report_date)}</span><h2>${esc(r.title)}</h2><p>${esc(d.lab_source||'Lab source not recorded')}</p></div><div class="health-ring"><strong>${d.health_score??'—'}</strong><span>HEALTH SCORE</span></div></header><section class="report-summary"><span class="eyebrow">COACH SUMMARY</span><p>${esc(r.summary||d.coach_summary||gen.overview||'No coach summary recorded.')}</p></section>${markers.length?`<section class="report-table"><div class="panel-head"><div><h3>Blood markers</h3><span class="sub">${markers.length} tested · ${flagged.length} requiring attention</span></div></div><div class="data-table"><div class="data-head"><span>Marker</span><span>Result</span><span>Reference</span><span>Status</span></div>${markers.map(m=>`<div class="data-row"><b>${esc(m.marker_name||m.name)}</b><span>${esc(m.value)} ${esc(m.unit||'')}</span><span>${esc(m.reference_range_low??'—')}–${esc(m.reference_range_high??'—')}</span><span class="marker-status">${esc(m.status||m.classification||'—')}</span></div>`).join('')}</div></section>`:''}${Object.keys(gen).length?recommendation('GENETIC INSIGHTS',gen,'#9d72d5'):''}<div class="recommendation-grid">${recommendation('NUTRITION',d.action_nutrition||gen.recommendations?.nutrition,'#4cc9a4')}${recommendation('TRAINING',d.action_training||gen.recommendations?.training,'#5da9e9')}${recommendation('SUPPLEMENTS',d.action_supplements||gen.recommendations?.supplements,'#d3a64b')}${recommendation('RECOVERY',d.action_recovery||gen.recommendations?.recovery,'#9d72d5')}</div>${d.action_followup?recommendation('FOLLOW-UP TESTING',d.action_followup,'#d98585'):''}${d.loom_url?`<a class="loom-card" href="${esc(d.loom_url)}" target="_blank" rel="noopener"><span>▶</span><div><b>Coach video walkthrough</b><small>${esc(d.loom_description||'Open Loom report review')}</small></div></a>`:''}<details class="source-json"><summary>Complete imported JSON</summary><pre class="source-record">${esc(JSON.stringify(d,null,2))}</pre></details></article>`}
boot();
